import { join } from 'node:path';
import { expect, test } from '@playwright/test';
import {
  HARNESS_CONFIG,
  harnessAvailable,
  startHarnessPreview,
} from '../test-support/harness.js';

/**
 * Visual regression of the scene harness (§7.1): 6 states at 2×, DOM text
 * hidden, animations disabled, zero pixel difference. Baselines exist only
 * for Linux CI and are regenerated by update-visual-baselines.yml.
 *
 * Mirrors HARNESS_STATES in apps/web/src/test-support/harness/fixtures.ts
 * (apps/e2e cannot import apps/web).
 */
const STATES = [
  'implement',
  'meeting',
  'conclusion-hush',
  'two-rows',
  'error-needs-you',
  'final-merged',
] as const;

test.skip(
  process.platform !== 'linux',
  'Visual baselines are compared on Linux CI only (§7.3).',
);
test.skip(
  !harnessAvailable(),
  `Waiting for the scene harness (apps/web/${HARNESS_CONFIG}).`,
);

let harness: Awaited<ReturnType<typeof startHarnessPreview>> | undefined;
test.beforeAll(async () => {
  harness = await startHarnessPreview();
});
test.afterAll(async () => {
  await harness?.stop();
});

for (const state of STATES) {
  test(`scene harness: ${state}`, async ({ page }) => {
    await page.goto(`${harness!.origin}/?state=${state}&scale=2`, {
      waitUntil: 'networkidle',
    });
    const scene = page.getByTestId('office-scene');
    await expect(scene).toBeVisible();
    await page.evaluate(async () => {
      await document.fonts.ready;
      await Promise.all(
        [...document.images].map((image) => image.decode().catch(() => {})),
      );
    });
    await expect(scene).toHaveScreenshot(`${state}.png`, {
      stylePath: join(import.meta.dirname, 'visual-hide-text.css'),
    });
  });
}
